undo.pseudocode:
def undo(log, losers):  # losers: COMMIT 없는 트랜잭션
    for rec in reversed(log):  # 최근 기록부터 역방향
        if not losers:
            break  # 모두 취소 완료
        if rec.tx not in losers:
            continue
        if rec.kind == 'UPDATE':
            write(rec.item, rec.before)  # Before Image 복원
        elif rec.kind == 'START':
            write_log('ABORT', rec.tx)
            losers.discard(rec.tx)

unification.pseudocode:
def unify(x, y, s):  # s: 치환(dict), 실패 시 None
    if s is None:
        return None
    if x == y:
        return s
    if is_var(x):
        return unify_var(x, y, s)
    if is_var(y):
        return unify_var(y, x, s)
    if isinstance(x, tuple) and isinstance(y, tuple):
        if len(x) != len(y):  # (함수명, 인자...) 형태
            return None
        for a, b in zip(x, y):  # 함수명·인자 순서대로
            s = unify(a, b, s)
        return s
    return None  # 상수·함수명 불일치

def unify_var(v, t, s):
    if v in s:
        return unify(s[v], t, s)
    if is_var(t) and t in s:
        return unify(v, s[t], s)
    if occurs(v, t, s):  # 순환 검사(Occurs Check)
        return None
    return {**s, v: t}

uniform-cost-search.pseudocode:
def ucs(start, goal, neighbors):
    pq = [(0, start)]  # (경로비용 g, 노드) 최소 힙
    best = {start: 0}
    parent = {start: None}
    while pq:
        g, n = heappop(pq)
        if g > best[n]:
            continue  # 낡은 항목: 더 싼 경로로 이미 처리
        if n == goal:  # 꺼낼 때 목표 검사 → 최적 보장
            return g, path(parent, n)
        for m, cost in neighbors(n):
            ng = g + cost
            if ng < best.get(m, INF):
                best[m] = ng
                parent[m] = n
                heappush(pq, (ng, m))
    return None  # 경로 없음

uninformed-search.pseudocode:
def graph_search(start, is_goal, expand, frontier):
    # frontier: 큐(FIFO) → BFS, 스택(LIFO) → DFS
    frontier.push(start)
    visited = {start}
    while not frontier.empty():
        n = frontier.pop()  # 꺼내는 순서가 전략을 결정
        if is_goal(n):
            return n
        for m in expand(n):  # 후계 함수(문제 정의)만 사용
            if m not in visited:
                visited.add(m)
                frontier.push(m)
    return None  # 해 없음

union-find.pseudocode:
parent = list(range(n))  # 처음엔 각자 루트
rank = [0] * n

def find(x):
    if parent[x] != x:
        parent[x] = find(parent[x])  # 경로 압축
    return parent[x]

def union(a, b):
    ra, rb = find(a), find(b)
    if ra == rb:
        return False  # 이미 같은 집합 (사이클)
    if rank[ra] < rank[rb]:
        ra, rb = rb, ra
    parent[rb] = ra  # 낮은 랭크 트리를 아래로
    if rank[ra] == rank[rb]:
        rank[ra] += 1
    return True

